local CombMaker = {}
local PRODUCTS = {
    iron_comb = { name = "Železni glavnik", ironCost = 2, woodCost = 2, leatherCost = 1, time = 4, cost = 125, prestige = 3, happiness = 2, description = "Železni glavnik za vsakodnevno uporabo." },
    bronze_comb = { name = "Bronast glavnik", bronzeCost = 2, ironCost = 1, woodCost = 2, leatherCost = 1, time = 6, cost = 310, prestige = 5, happiness = 3, description = "Bronast glavnik za boljše lase." },
    silver_comb = { name = "Srebrni glavnik", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 10, cost = 760, prestige = 10, happiness = 4, description = "Srebrni glavnik za plemiške lase." },
    gilded_comb = { name = "Pozlačeni glavnik", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 14, cost = 1650, prestige = 19, happiness = 5, description = "Pozlačeni glavnik za dvorne lase." },
    jewel_set_comb = { name = "Draguljasti glavnik", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 18, cost = 3600, prestige = 35, happiness = 7, description = "Draguljasti glavnik za kraljeve lase." },
    royal_sovereign_comb = { name = "Kraljevski suvereni glavnik", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 25, cost = 7900, prestige = 67, happiness = 13, description = "Suvereni glavnik z biseri za krono." },
}
local BUILDINGS = {
    comb_workshop = { name = "Glavnična delavnica", cost = { gold = 295, wood = 175, stone = 120, iron = 6 }, upkeep = 5, qualityBonus = 5 },
    comb_house = { name = "Glavnična hiša", cost = { gold = 1100, wood = 350, stone = 250, silver = 6, iron = 6 }, upkeep = 23, qualityBonus = 18 },
    master_comb_atelier = { name = "Mojstrski glavnični atelje", cost = { gold = 2850, wood = 410, stone = 490, silver = 32, gold = 6 }, upkeep = 67, qualityBonus = 30 },
    sovereign_comb_palace = { name = "Suverena glavnična palača", cost = { gold = 12400, wood = 635, stone = 800, gold = 79, jewel = 18 }, upkeep = 245, qualityBonus = 55, prestigeBonus = 50 },
}
CombMaker.ironStock = 12; CombMaker.bronzeStock = 10; CombMaker.woodStock = 16; CombMaker.leatherStock = 8; CombMaker.silverStock = 8; CombMaker.goldStock = 6; CombMaker.jewelStock = 4; CombMaker.pearlStock = 4
CombMaker.productStock = {}; CombMaker.buildings = {}; CombMaker.maker = nil; CombMaker.activeMaking = {}; CombMaker.totalProducts = 0; CombMaker.dayTimer = 0
function CombMaker.init() CombMaker.ironStock=12; CombMaker.bronzeStock=10; CombMaker.woodStock=16; CombMaker.leatherStock=8; CombMaker.silverStock=8; CombMaker.goldStock=6; CombMaker.jewelStock=4; CombMaker.pearlStock=4; CombMaker.productStock={}; CombMaker.buildings={}; CombMaker.maker=nil; CombMaker.activeMaking={}; CombMaker.totalProducts=0; CombMaker.dayTimer=0; print("[CombMaker] Royal Comb Maker System initialized (6 products, 4 buildings)") end
function CombMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CombMaker.maker={name=n or ("Glavnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Glavnikar najet: %s (spretnost: %d)",CombMaker.maker.name,s),"success") end; return true end
function CombMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CombMaker.build(id) local ok,e=CombMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CombMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CombMaker.getQualityBonus() local b=0; for _,bd in ipairs(CombMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CombMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CombMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CombMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CombMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CombMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CombMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CombMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CombMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CombMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CombMaker.buildings==0 then return false,"Potrebna glavnična delavnica" end; if not CombMaker.maker then return false,"Potreben glavnikar" end; return true end
function CombMaker.make(pt,qty) qty=qty or 1; local ok,e=CombMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CombMaker.ironStock=CombMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CombMaker.bronzeStock=CombMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CombMaker.woodStock=CombMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CombMaker.leatherStock=CombMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CombMaker.silverStock=CombMaker.silverStock-d.silverCost*qty end; if d.goldCost then CombMaker.goldStock=CombMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CombMaker.jewelStock=CombMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CombMaker.pearlStock=CombMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CombMaker.maker then t=math.max(1,t-math.floor(CombMaker.maker.skill/13)) end; table.insert(CombMaker.activeMaking,{id="comb_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CombMaker.completeMaking(m) local q=1.0+(CombMaker.getQualityBonus()/100); if CombMaker.maker then q=q+(CombMaker.maker.skill/140) end; q=math.min(2.5,q); CombMaker.productStock[m.productType]=(CombMaker.productStock[m.productType] or 0)+m.quantity; CombMaker.totalProducts=CombMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CombMaker.maker then CombMaker.maker.itemsMade=CombMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CombMaker.maker.skill=math.min(100,CombMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Glavnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"comb.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CombMaker.update(dt) if not _G.state then return end; CombMaker.dayTimer=CombMaker.dayTimer+dt; if CombMaker.dayTimer>=30 then CombMaker.dayTimer=0; for i=#CombMaker.activeMaking,1,-1 do local m=CombMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CombMaker.completeMaking(m); table.remove(CombMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CombMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CombMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CombMaker.getStats() return {ironStock=CombMaker.ironStock,bronzeStock=CombMaker.bronzeStock,woodStock=CombMaker.woodStock,leatherStock=CombMaker.leatherStock,silverStock=CombMaker.silverStock,goldStock=CombMaker.goldStock,jewelStock=CombMaker.jewelStock,pearlStock=CombMaker.pearlStock,productStock=CombMaker.productStock,numBuildings=#CombMaker.buildings,hasMaker=CombMaker.maker~=nil,makerName=CombMaker.maker and CombMaker.maker.name or "—",makerSkill=CombMaker.maker and CombMaker.maker.skill or 0,activeMaking=#CombMaker.activeMaking,totalProducts=CombMaker.totalProducts} end
return CombMaker
